'use strict';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal'), drawer=$('#coach');
let data=null,page='today',selected=null,proposalId=null,chatSession=null,profileDraft=null,onboardStep=0,timerInterval=null,timerStart=0,timerSession=null,sending=false,pendingText='';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-12 5 2 2 4-4"/>',growth:'<path d="M4 20V5m0 15h17M7 15l5-5 4 3 5-8m-5 0h5v5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 2v4m-2-2h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',leaf:'<path d="M20 3C7 1 2 8 6 15s15 3 14-12ZM4 21 16 8"/>',check:'<path d="m5 12 4 4L19 6"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m9 10 3-3 3 4 4 1M12 7l-2 8-4 6m4-6 5 2 1 5M5 12l4-2"/>',strength:'<path d="m3 7 4-4m10 18 4-4M2 11l9-9m2 20 9-9M7 7l10 10M5 9l10 10m-6-14 10 10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',send:'<path d="m4 4 17 8-17 8 3-8Zm3 8h14"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',edit:'<path d="m14 4 6 6M4 20l2-7L17 2l5 5-11 11ZM3 22h18"/>',play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Zm-4 10 3 3 5-6"/>',logout:'<path d="M10 3H4v18h6m5-15 6 6-6 6M8 12h13"/>'};
const I=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.leaf}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const goalNames={habit:'建立运动规律',energy:'改善日常体能',strength:'打好力量基础',endurance:'提升基础耐力'}, dayNames=['周一','周二','周三','周四','周五','周六','周日'];
const brand=()=>'<span class="brand"><img src="/static/icon.svg" alt=""><span>Sports<em>Wise</em></span></span>';
const fmt=(v,opts={month:'long',day:'numeric'})=>new Date(v+'T12:00:00').toLocaleDateString('zh-CN',opts);
const dateAdd=(v,n)=>{const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const state=()=>data?.state;
const allPlans=()=>{const m=new Map();for(const p of [...(state()?.history||[]),...(state()?.plan?[state().plan]:[])])m.set(p.week,p);return [...m.values()]};
const allSessions=()=>allPlans().flatMap(p=>p.sessions);
const sessionBy=id=>allSessions().find(s=>s.id===id)||state()?.upcoming?.sessions.find(s=>s.id===id);
const recordFor=s=>state().records.find(r=>r.session_id===s?.id);
const iconFor=s=>s?.kind==='strength'?'strength':s?.kind==='rest'?'leaf':'walk';
const isDone=s=>['completed','partial'].includes(recordFor(s)?.status);
const focusSession=()=>allSessions().find(s=>s.date===data.today);
function art(){return `<svg class="hero-art" viewBox="0 0 330 300" fill="none" aria-hidden="true"><defs><linearGradient id="hill" x1="130" y1="75" x2="250" y2="280" gradientUnits="userSpaceOnUse"><stop stop-color="#d8e5bc"/><stop offset="1" stop-color="#b5cc8b"/></linearGradient></defs><circle cx="213" cy="86" r="53" fill="#e1eacb"/><circle cx="213" cy="86" r="34" stroke="#d3dfba"/><path d="M-8 264C74 168 110 210 166 133C225 52 293 117 350 67V310H-8Z" fill="url(#hill)"/><path d="M76 303c45-63 77-42 106-87s19-72 61-87 63-10 96-40" stroke="#edf3df" stroke-width="21"/><path d="M76 303c45-63 77-42 106-87s19-72 61-87 63-10 96-40" stroke="#c7d7ad" stroke-dasharray="4 6"/><path d="M292 270c-18-33-8-46 5-63m-4 39-18-12m19-1 17-15M54 249c-8-19-1-28 8-35" stroke="#8da667" stroke-width="2" stroke-linecap="round"/><ellipse cx="197" cy="231" rx="32" ry="6" fill="#6d8659" opacity=".12"/><path d="m197 151-11 37-22 32m24-33 25 17 13 24" stroke="#344c35" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="m190 126 18 9-11 30-19-7Z" fill="#f6f8ed"/><path d="m192 135-17 15-18-6m43-6 13 18 17-5" stroke="#b38c68" stroke-width="6" stroke-linecap="round"/><circle cx="202" cy="116" r="11" fill="#b38c68"/><path d="M190 115c-4-17 19-23 23-7l-12 1-5 9Z" fill="#344c35"/><path d="m158 222 9 2m57 5 10 1" stroke="#506443" stroke-width="6" stroke-linecap="round"/><path d="M272 170v-34m-12 17 12-22 12 22Z" stroke="#6d8952" stroke-width="2"/><path d="M111 210v-23m-9 12 9-17 9 17Z" stroke="#91a974" stroke-width="2"/></svg>`}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),4200)}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const out=await res.json().catch(()=>({detail:'服务暂时不可用'}));if(!res.ok){if(res.status===409){await load();}throw new Error(typeof out.detail==='string'?out.detail:'请检查填写的内容和范围')}return out}
async function mutate(path,body={},method='POST'){const out=await api(path,method,{revision:data.revision,...body});if(out.state){data=out;render();}return out}
async function load(){try{data=await api('/state');render()}catch(e){if(!data)landing();else toast(e.message)}}
function showModal(title,html){if(timerInterval){clearInterval(timerInterval);timerInterval=null;}modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${I('close')}</button></div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0}
function closeModal(){modal.close();if(timerInterval){clearInterval(timerInterval);timerInterval=null;}}
function landing(){data=null;app.innerHTML=`<main class="landing"><nav class="landing-nav">${brand()}<button class="btn ghost" data-action="login">登录 / 开始 ${I('arrow')}</button></nav><section class="landing-main"><div><div class="eyebrow">YOUR PACE. YOUR PROGRESS.</div><h1 class="serif">运动有方向，<br>进步有自己的节奏。</h1><p>从你现在的状态出发，一起找到合适的运动安排。<br>生活会变化，计划也可以。每一次小小的坚持，都算数。</p><div class="landing-proof">“今天只有十分钟” → 预览调整 → 采用<br><span>真实反馈留在记录里，下一周接着调整。</span></div><div class="actions"><button class="btn primary" data-action="new-demo">先为我制定计划 ${I('arrow')}</button><button class="btn ghost" data-action="demo">看看示例计划</button></div><p style="font-size:10px;margin-top:22px">不需要手表，也不用先变得自律。就从现在的你开始。</p></div><div class="landing-visual">${art()}<div class="floating-note">今天，做一点适合自己的。<small>认识自己 → 开始行动 → 慢慢进步</small></div></div></section><section class="landing-features"><div>${I('user')}<strong>先了解你，再安排训练</strong><p>目标、时间、兴趣与现状，共同决定你的起点。</p></div><div>${I('calendar')}<strong>安排可以随生活调整</strong><p>忙一点、累一点，或想换一种，都能商量。</p></div><div>${I('growth')}<strong>看到进步，也理解进步</strong><p>用实际反馈调整下一步，逐渐学会怎么练。</p></div></section>${footer()}</main>`}
function footer(){return `<footer class="footer"><span>WAYWISE · 帮助希望提升的人提升　<button class="text-btn" data-action="privacy">数据与隐私</button></span><span>一般运动建议 · 不替代医疗或专项指导　<a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener">沪ICP备2025127932号</a></span></footer>`}
function render(){if(!data)return landing();const p=state().profile;const labels={today:'今天',plan:'计划',growth:'成长',me:'我的'};app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="brand-note">找到自己的运动节奏</div><nav class="nav" aria-label="主导航">${Object.entries(labels).map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${I({today:'home',plan:'calendar',growth:'growth',me:'user'}[id])}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-quote">慢慢来，<br>每一步都在靠近。</div><div class="profile-chip"><div class="avatar">${esc((p?.name||'你').slice(0,1))}</div><div><strong>${esc(p?.name||'新的开始')}</strong><small>${data.user.demo?(state().demo_mode==='empty'?'独立试用空间':'独立演示空间'):'我的运动旅程'}</small></div><button class="text-btn" data-action="logout" aria-label="退出" style="margin-left:auto">${I('logout')}</button></div></div></aside><main class="workspace"><header class="topbar"><div class="crumb">我的运动旅程 ${I('chevron')} <span>${labels[page]}</span></div><span class="mobile-brand">${brand()}</span><div class="top-actions"><span class="date-label">${esc(fmt(data.today,{year:'numeric',month:'long',day:'numeric',weekday:'long'}))}</span>${data.user.demo?`<span class="pill demo">${state().demo_mode==='empty'?'从零试用':'示例体验'}</span>`:''}<button class="icon-btn" data-action="notices" aria-label="查看提醒">${I('bell')}${data.notices.some(n=>!n.read)?'<span class="dot"></span>':''}</button></div></header><div class="page">${data.user.demo&&state().demo_mode!=='empty'?`<div class="banner demo-banner"><p>你正在查看虚构的示例计划和运动记录。</p><button class="text-btn" data-action="new-demo">从零制定我的计划 ${I('arrow')}</button></div>`:''}${state().risk?.message?`<div class="banner">${I('shield')}<p>${esc(state().risk.message)}</p><button class="text-btn" data-action="onboard">更新身体情况 ${I('arrow')}</button></div>`:''}${({today:todayPage,plan:planPage,growth:growthPage,me:mePage}[page])()}</div>${footer()}</main></div>`;if(!drawer.hidden)renderCoach()}
function heading(en,title,sub,right=''){return `<div class="eyebrow">${en}</div><div class="heading-row"><div><h1 class="serif">${title}</h1><p class="subheading">${sub}</p></div>${right}</div>`}
function noProfile(){return `<div class="card empty"><div class="empty-icon">${I('leaf')}</div><h2 class="serif">从了解现在的你开始</h2><p>告诉我你的运动现状、目标和可用时间。<br>我们一起找到第一周合适的安排。</p><button class="btn primary" data-action="onboard">建立我的运动档案 ${I('arrow')}</button></div>`}
function weekRail(plan){if(!plan)return '';return `<div class="week-rail">${plan.sessions.map(s=>{const d=new Date(s.date+'T12:00:00'),r=recordFor(s);return `<button class="day ${s.date===data.today?'today':''} ${isDone(s)?'done':''} ${selected===s.id?'selected':''}" data-action="select-day" data-id="${s.id}" aria-label="${esc(fmt(s.date))} ${esc(s.title)}"><span class="weekday">${dayNames[(d.getDay()+6)%7]}</span><span class="day-number">${d.getDate()}</span><span class="day-mark">${I(isDone(s)?'check':iconFor(s))}</span><span class="day-type">${r?({completed:'已完成',partial:'部分完成',skipped:'未完成',rest:'已休息'}[r.status]):s.kind==='rest'?'恢复休息':s.kind==='strength'?'基础力量':'轻松活动'}</span></button>`}).join('')}</div>`}
function weekCard(plan,detail=false){return `<section class="card week-card ${detail?'':'section'}"><div class="card-header"><h2>${detail?'一周的安排':'这一周，稳稳向前'}</h2><span class="mini">${fmt(plan.week,{month:'numeric',day:'numeric'})} — ${fmt(dateAdd(plan.week,6),{month:'numeric',day:'numeric'})}</span></div>${weekRail(plan)}${detail?trainingDetail(plan.sessions.find(s=>s.id===selected)||plan.sessions.find(s=>s.date===data.today)||plan.sessions[0]):''}</section>`}
function progressCard(){const s=data.stats,ratio=s.planned?Math.min(1,s.completed/s.planned):0;return `<section class="card"><div class="card-header"><h2>本周的小积累</h2><span class="mini">${s.unknown?'含 '+s.unknown+' 次未知记录':'每一次都算数'}</span></div><div class="week-progress"><div class="ring"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="47" fill="none" stroke="#eff2e8" stroke-width="7"/><circle cx="55" cy="55" r="47" fill="none" stroke="#829b5d" stroke-width="7" stroke-linecap="round" stroke-dasharray="${ratio*295.3} 295.3"/></svg><div class="ring-label"><strong>${s.completed}<small> / ${s.planned}</small></strong><span>已记录活动</span></div></div><div class="ring-description"><strong>${s.completed?'给自己一点肯定':'第一步，可以很小'}</strong><p>已经活动了 ${s.minutes} 分钟<br>${s.completed?'继续保持自己的节奏。':'从今天的一次轻松活动开始。'}</p></div></div><div class="progress-foot"><span>原始 / 当前计划</span><strong>${s.original_minutes} / ${s.planned_minutes} 分钟</strong></div></section>`}
function miniChart(){const points=[];for(let w=3;w>=0;w--){const end=dateAdd(data.today,-7*w+1),start=dateAdd(end,-7);points.push(state().records.filter(r=>r.date>=start&&r.date<end&&['completed','partial'].includes(r.status)).reduce((a,r)=>a+r.minutes,0))}const max=Math.max(...points,30),xs=[10,90,170,250],ys=points.map(v=>90-v/max*65);return `<svg class="mini-chart" viewBox="0 0 260 105" role="img" aria-label="最近四周活动分钟数 ${points.join('、')}"><path d="M10 25H250M10 57H250M10 90H250" stroke="#eff1e9" stroke-dasharray="3 5"/><path d="M${xs.map((x,i)=>x+','+ys[i]).join(' L')} L250,100 L10,100Z" fill="#edf2e1"/><path d="M${xs.map((x,i)=>x+','+ys[i]).join(' L')}" stroke="#829b5d" fill="none" stroke-width="2"/>${points.map((v,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="3" fill="#829b5d"/><text x="${xs[i]}" y="${ys[i]-10}" font-size="9" text-anchor="middle" fill="#8a957c">${v}</text>`).join('')}</svg><div class="chart-labels"><span>四周前起</span><span>最近一周</span></div><div class="legend">实际记录的活动时长 · 分钟</div>`}
function todayPage(){const p=state().profile;if(!p)return heading('A FRESH START','你好，新的开始。','不用一次改变很多，先找到适合自己的第一步。')+noProfile();const s=focusSession(),r=s?recordFor(s):null,done=isDone(s),rest=!s||s.kind==='rest';return `${heading('A LITTLE EVERY DAY',`${esc(p.name)}，今天也向前一点。`,'不着急追赶谁，找到自己的节奏就好。',`<span class="pill">${esc(state().plan?.phase||'认识自己')}</span>`)}<div class="grid-main"><div><section class="hero"><div class="hero-text"><div class="hero-kicker">${I(rest?'leaf':'sun')} ${done?'今天的积累已记下':s?.date===data.today?'为今天准备的安排':'留一点空间，给自己'}</div><h2 class="serif">${rest?'今天好好恢复，<br>也是在向前。':done?(r.status==='partial'?'完成一点，<br>也值得记下。':'又一次，<br>为自己做到。'):s.kind==='strength'?'练一点力量，<br>让日常更从容。':'走一小段，<br>离更好的自己近一点。'}</h2><p>${esc(done?'身体的改变需要时间，今天的行动已经是其中一部分。':s?.purpose||'今天可以轻松活动，或者单纯休息。')}</p>${!rest?`<div class="hero-meta"><span>${I('clock')}${done?(r.minutes===0?'实际不足 1 分钟':'实际 '+r.minutes+' 分钟'):s.minutes+' 分钟计划'}</span><span>${done?'原安排 '+s.minutes+' 分钟':I(iconFor(s))+(s.kind==='strength'?'基础力量':'轻松活动')}</span><span>${I('leaf')}轻松强度</span></div>`:''}</div>${art()}<div class="hero-actions"><button class="btn primary" data-action="${done?'feedback':rest?'free-record':'training'}" ${s&&!rest?`data-id="${s.id}"`:''}>${I(done?'check':rest?'edit':'play')}${done?'查看 / 修改反馈':rest?'记录自主活动':'看看今天怎么练'}</button><button class="text-btn" data-action="coach">${rest?'和教练聊聊':'今天想调整一下'} ${I('arrow')}</button></div></section>${state().plan?weekCard(state().plan):''}<div class="two-cards section"><section class="card insight"><div class="insight-label">${I('book')} 今天，懂一点运动</div><blockquote class="serif">“适合自己的安排，<br>才有机会变成习惯。”</blockquote><p>忙碌时缩短一点，疲惫时缓一缓。<br>调整是为了继续，记录帮你认识自己。</p><button class="text-btn" data-action="learn" style="margin-top:17px">为什么不需要补欠课 ${I('arrow')}</button></section><section class="card"><div class="card-header"><h2>进步，有自己的路线</h2>${I('growth')}</div><div class="route-mini"><div class="route-dot">01</div><div><strong>认识现在的自己</strong><small>找到起点和生活中的空间</small></div><span class="status-tag">已开始</span></div><div class="route-mini"><div class="route-dot">02</div><div><strong>练出可以持续的节奏</strong><small>用每次反馈调整下一步</small></div><span class="status-tag">进行中</span></div><div class="route-mini"><div class="route-dot">03</div><div><strong>准备好了，再向前一点</strong><small>根据实际表现与恢复决定</small></div></div></section></div></div><div class="right-column">${progressCard()}<section class="card coach-card section"><div class="card-header"><h2>你的运动教练</h2><div class="coach-spark">${I('spark')}</div></div><p>${esc(data.direction[1])}</p><button class="btn lime" data-action="coach">聊聊我的安排 ${I('arrow')}</button><div class="coach-suggestions"><button data-action="quick-coach" data-text="今天只有十分钟">今天时间有点紧</button><button data-action="quick-coach" data-text="今天想换成室内活动">想换一种练法</button></div></section><section class="card trend-card section"><div class="card-header"><h2>慢慢积累的变化</h2><button class="text-btn" data-page="growth">查看 ${I('arrow')}</button></div>${miniChart()}</section></div></div>`}
function trainingDetail(s){if(!s)return '';const record=recordFor(s),futureQueued=!!state().upcoming?.sessions.some(x=>x.id===s.id);return `<div class="training-detail"><div class="training-title"><div><h3>${esc(s.title)}</h3><span class="muted small-text">${fmt(s.date,{month:'long',day:'numeric',weekday:'long'})} · ${esc(s.purpose)}</span></div>${s.kind!=='rest'?`<span class="pill">${s.minutes} 分钟</span>`:''}</div>${s.steps.map((x,i)=>`<div class="step"><div class="step-index">${String(i+1).padStart(2,'0')}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div><span class="step-time">${x.minutes} 分钟</span></div>`).join('')}${s.kind==='rest'?'<p class="small-text muted">不需要把每一天填满。今天可以按自己的感受轻松活动，或者好好休息。</p>':''}${record?`<p class="privacy-note">已记录：${{completed:'完整完成',partial:'部分完成',skipped:'未完成',rest:'休息'}[record.status]} · ${record.minutes} 分钟 · ${{easy:'轻松',okay:'合适',hard:'吃力'}[record.effort]}${record.note?' · '+esc(record.note):''}</p>`:''}<div class="actions">${s.kind!=='rest'&&s.date===data.today&&!record?`<button class="btn primary" data-action="training" data-id="${s.id}">${I('play')} 开始这次训练</button>`:''}${s.date<=data.today&&s.kind!=='rest'?`<button class="btn ${record?'ghost':'primary'}" data-action="feedback" data-id="${s.id}">${I('edit')}${record?'修改反馈':'记录完成情况'}</button>`:''}${s.kind!=='rest'&&s.date>=data.today&&!record&&!futureQueued?`<button class="btn ghost" data-action="adjust" data-id="${s.id}">调整这次安排</button>`:''}${s.kind==='rest'&&s.date<=data.today?'<button class="btn ghost" data-action="free-record">记录自主活动</button>':''}</div><div class="sources">动作时间包含休息，不要求持续重复。有异常不适时先停止。<br>参考：<a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener">NHS 基础力量动作</a> · <a href="https://www.niddk.nih.gov/health-information/weight-management/tips-get-active/tips-starting-physical-activity" target="_blank" rel="noopener">从少量活动开始</a></div></div>`}
function planPage(){const p=state().plan;if(!p)return heading('MAKE ROOM FOR MOVEMENT','给运动，留一点位置。','计划从你的生活出发，也可以随着生活调整。')+noProfile();return `${heading('YOUR WEEK, YOUR WAY','安排有方向，也有余地。','计划不是一张不能改的课表，是我们一起商量的下一步。',`<button class="btn ghost small" data-action="onboard">${I('edit')} 修改偏好</button>`)}<div class="grid-main"><div class="stack"><div class="plan-reason">${esc(p.reason)}${p.rationale?`<br>${esc(p.rationale)}`:''}<br><span class="muted">${goalNames[state().profile.goal]} · 每次最多 ${state().profile.minutes} 分钟 · ${state().profile.days.map(i=>dayNames[i]).join('、')}</span></div>${weekCard(p,true)}${state().upcoming?`<div class="card"><div class="card-header"><h2>下一周也有了方向</h2><span class="badge">${fmt(state().upcoming.week)}</span></div><p class="small-text muted">${esc(state().upcoming.reason)}</p>${weekRail(state().upcoming)}${selected&&state().upcoming.sessions.some(s=>s.id===selected)?trainingDetail(state().upcoming.sessions.find(s=>s.id===selected)):''}<p class="small-text muted">到新一周时自动接上。今天仍按本周安排进行。如需改变长期偏好，可修改运动档案后重新安排。</p></div>`:''}<section class="card"><div class="card-header"><h2>计划改变的轨迹</h2>${state().history.some(x=>x.week===p.week)?'<button class="text-btn" data-action="undo">撤回上次调整 '+I('history')+'</button>':''}</div><div class="version-list"><strong>当前 · 第 ${p.version} 版</strong><p>${esc(p.reason)}</p></div>${state().history.filter(x=>x.week===p.week).slice(-3).reverse().map(x=>`<div class="version-list"><strong>第 ${x.version} 版</strong><p>${esc(x.reason)}</p></div>`).join('')}</section></div><div class="stack"><section class="card insight"><div class="card-header"><h2>这一阶段：适应与校准</h2>${I('leaf')}</div><div class="timeline"><div class="timeline-item current"><h3>找到合适的起点</h3><p>先熟悉安排，留意活动后和第二天的感受。</p></div><div class="timeline-item"><h3>把反馈带进下一周</h3><p>时间不合适就调整，觉得吃力就缓一缓。</p></div><div class="timeline-item"><h3>准备好了，再进阶</h3><p>需要真实训练和恢复反馈，不按日期自动加量。</p></div></div></section><section class="card"><div class="card-header"><h2>下一周，怎么安排？</h2>${I('calendar')}</div><p class="small-text muted">${esc(data.direction[1])}</p>${state().upcoming?'<span class="pill">下一周已经安排好</span>':`<button class="btn primary" data-action="next-week">预览下一周安排 ${I('arrow')}</button>`}</section><section class="card coach-card"><div class="card-header"><h2>生活变了，计划也能变</h2>${I('spark')}</div><p>加班、出差，或者只想轻松一点。告诉我，我们一起调整。</p><button class="btn lime" data-action="coach">和教练商量 ${I('arrow')}</button></section></div></div>`}
function growthPage(){const completed=state().records.filter(r=>['completed','partial'].includes(r.status)),minutes=completed.reduce((a,r)=>a+r.minutes,0),latest=state().reviews.at(-1);return `${heading('PROGRESS BEYOND NUMBERS','每一步，都留下了痕迹。','回头看看做过的事，也慢慢认识自己的节奏。',`<button class="btn ghost small" data-action="free-record">${I('edit')} 记录活动</button>`)}<div class="stat-grid"><div class="card stat-box"><small>累计活动</small><strong>${completed.length}<span>次</span></strong><p>完整与部分完成分别保留</p></div><div class="card stat-box"><small>实际投入</small><strong>${minutes}<span>分钟</span></strong><p>来自你的实际记录</p></div><div class="card stat-box"><small>本周记录</small><strong>${data.stats.completed}<span>/ ${data.stats.planned} 次</span></strong><p>${data.stats.unknown} 次过去的安排情况未知</p></div><div class="card stat-box"><small>记录后的感受</small><strong>${completed.filter(r=>r.effort==='easy').length}<span>次轻松</span></strong><p>感受也是理解自己的线索</p></div></div><div class="grid-main"><div class="stack"><section class="card"><div class="card-header"><h2>活动的节奏</h2><span class="mini">最近四周 · 实际分钟数</span></div>${miniChart()}<p class="small-text muted" style="margin-bottom:0">时长不代表全部效果。条件相近的表现，才更适合互相比较。</p></section><section class="card"><div class="card-header"><h2>回顾这一段</h2><div class="flex"><button class="text-btn" data-action="review" data-cadence="week">本周复盘</button><span class="muted">·</span><button class="text-btn" data-action="review" data-cadence="month">本月回顾</button></div></div>${latest?`<div class="eyebrow">${latest.cadence==='week'?'WEEKLY REFLECTION':'MONTHLY REFLECTION'} · ${latest.start}</div><h3 class="serif" style="font-size:22px;font-weight:500;line-height:1.7">${esc(latest.headline)}</h3><div class="review-body">${esc(latest.summary)}<strong>下一步的建议</strong>${esc(latest.next)}<strong>留一个问题给自己</strong>${esc(latest.question)}</div><div class="actions"><button class="btn primary" data-action="next-week">看看下一周怎么安排 ${I('arrow')}</button></div>`:`<div class="empty" style="padding:20px 5px"><div class="empty-icon">${I('book')}</div><p>每一次记录，都会让复盘更有依据。<br>先看看这周已经发生了什么。</p><button class="btn ghost" data-action="review" data-cadence="week">生成本周回顾</button></div>`}</section></div><div class="stack"><section class="card insight"><div class="insight-label">${I('spark')} 下一步，不用着急</div><blockquote class="serif" style="font-size:18px">${esc(data.direction[1])}</blockquote><p>进步也包括更了解自己的时间、兴趣和恢复需要。</p></section><section class="card"><div class="card-header"><h2>最近的运动记录</h2><span class="mini">${state().records.length} 条</span></div>${state().records.length?state().records.slice(-8).reverse().map(r=>`<div class="record-row"><div class="record-icon">${I(r.status==='rest'?'leaf':r.status==='skipped'?'history':'check')}</div><div><p>${esc(r.activity||sessionBy(r.session_id)?.title||'训练记录')}</p><small>${fmt(r.date,{month:'numeric',day:'numeric'})} · ${{completed:'完成',partial:'部分完成',skipped:'未完成',rest:'休息'}[r.status]} · ${{easy:'轻松',okay:'合适',hard:'吃力'}[r.effort]}</small></div><span class="record-min">${r.minutes}<small> 分钟</small></span></div>`).join(''):'<p class="small-text muted">这里会留下你的实际活动记录。</p>'}</section></div></div>`}
function mePage(){const p=state().profile,s=state().settings;return `${heading('GET TO KNOW YOURSELF','了解自己，才好向前。','你的目标、现实生活和身体感受，都值得被认真对待。')}<div class="settings-grid"><div class="stack"><section class="card"><div class="card-header"><h2>我的运动档案</h2><button class="text-btn" data-action="onboard">${I('edit')} ${p?'修改':'建立'}</button></div>${p?`<dl class="profile-summary"><div><dt>我的称呼</dt><dd>${esc(p.name)}</dd></div><div><dt>当前目标</dt><dd>${goalNames[p.goal]}</dd></div><div><dt>为什么运动</dt><dd>${esc(p.motivation)||'暂未填写'}</dd></div><div><dt>当前状态</dt><dd>${esc(p.current)||({beginner:'刚开始运动',returning:'重新开始',regular:'已有一定习惯'}[p.level])}</dd></div><div><dt>可用时间</dt><dd>${p.days.map(i=>dayNames[i]).join('、')}<br>每次最多 ${p.minutes} 分钟</dd></div><div><dt>喜欢的方式</dt><dd>${p.likes.map(x=>x==='walking'?'步行活动':'基础力量').join('、')}</dd></div><div><dt>身体限制</dt><dd>${esc(p.limitations)||'未报告特殊限制'}<small class="muted">（你的自述）</small></dd></div></dl>`:'<p class="small-text muted">先建立一份档案，让安排从你现在的状态出发。</p><button class="btn primary" data-action="onboard">开始建立</button>'}</section><section class="card"><div class="card-header"><h2>数据由你掌握</h2>${I('shield')}</div><p class="small-text muted">必要训练记录和反馈保存在服务端，用于跨次调整和定期复盘。个人计划默认私密。使用 AI 教练时，会发送必要档案、近期记录和对话作为上下文。</p><div class="privacy-note">${data.user.demo?(state().demo_mode==='empty'?'这是从零开始的独立试用空间。首次注册时可选择保存这次资料；试用期间不会发送邮件。':'你正在独立示例空间中。历史记录是虚构的；修改档案会保留示例历史，也可以从零试用。'):'当前账号：'+esc(data.user.email)}<br>${data.capabilities.ai?'AI 教练已连接；具体安排仍受训练模板和程序约束。':'当前为基础教练模式：规则制定安排，支持有限的中文调整指令。'}<br>${data.capabilities.mail?'邮件通道已配置。':'邮件尚未配置，当前可使用站内提醒。'}</div><div class="actions"><a class="btn ghost" href="/api/export">${I('download')} 导出我的数据</a><button class="btn ghost" data-action="${data.user.demo?'login':'logout'}">${I(data.user.demo?'user':'logout')}${data.user.demo?'登录正式账号':'退出登录'}</button></div><button class="text-btn" data-action="delete" style="color:#a58c78;margin-top:20px">${data.user.demo?'删除演示空间':'删除账号和训练数据'}</button></section></div><section class="card"><div class="card-header"><h2>按你的节奏提醒</h2>${I('bell')}</div><form id="settings-form">${[['daily','训练日前提醒','休息日保持安静'],['weekly','每周复盘','周一回看上周，商量下一步'],['monthly','每月回顾','月初回看上个月的积累'],['followup','未记录时跟进一次','提醒后仍未记录，再轻轻问一下'],['email','同时发送邮件',data.capabilities.mail&&!data.user.demo?'邮件默认不包含身体和健康细节':'当前不可用，站内提醒仍可使用']].map(([name,label,sub])=>`<label class="toggle-row"><span>${label}<small>${sub}</small></span><input type="checkbox" class="switch" name="${name}" ${s[name]?'checked':''} ${name==='email'&&(!data.capabilities.mail||data.user.demo)?'disabled':''} aria-label="${label}"></label>`).join('')}<div class="form-grid" style="margin-top:23px"><div class="form-field"><label for="remind-time">提醒时间</label><input id="remind-time" type="time" name="time" value="${esc(s.time)}" required></div><div class="form-field"><label for="tone">跟进方式</label><select id="tone" name="tone"><option value="gentle" ${s.tone==='gentle'?'selected':''}>轻提醒</option><option value="standard" ${s.tone==='standard'?'selected':''}>标准跟进</option><option value="firm" ${s.tone==='firm'?'selected':''}>更主动地督促</option></select></div><div class="form-field"><label for="quiet-start">安静时段开始</label><input id="quiet-start" type="time" name="quiet_start" value="${esc(s.quiet_start)}" required></div><div class="form-field"><label for="quiet-end">安静时段结束</label><input id="quiet-end" type="time" name="quiet_end" value="${esc(s.quiet_end)}" required></div></div><div class="form-field"><label for="zone">我的时区</label><select id="zone" name="timezone">${['Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Europe/London','America/New_York','America/Los_Angeles','Australia/Sydney'].map(z=>`<option ${s.timezone===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="form-field"><label for="paused">暂停提醒至</label><input id="paused" type="date" name="paused_until" value="${esc(s.paused_until)}"><small>留空表示正常提醒；连续两周没有访问时，主动跟进也会暂停。</small></div><button class="btn primary" type="submit">保存提醒偏好 ${I('check')}</button><p id="settings-error" class="error" role="alert"></p></form></section></div>`}
function login(){showModal('欢迎，开始你的运动旅程',`<p class="intro">用邮箱验证码登录。第一次登录会建立新账号。<br>你的个人训练记录默认私密。</p><form id="login-form"><div class="form-field"><label for="email">邮箱</label><input id="email" name="email" type="email" placeholder="you@example.com" required autocomplete="email"></div><div class="form-field"><label for="invite">邀请码（如需）</label><input id="invite" name="invite" placeholder="内测邀请码" autocomplete="off"></div><div class="flex"><input name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="6 位验证码" aria-label="验证码"><button class="btn ghost" type="button" data-action="send-code" style="flex-shrink:0">获取验证码</button></div><div id="login-info" class="small-text muted" style="margin-top:12px"></div>${data?.user.demo&&state()?.demo_mode==='empty'&&state()?.profile?'<label class="check-row"><input type="checkbox" name="import_trial" checked>首次注册时，将这次从零试用的档案和运动记录保存到正式账号</label><small class="muted">已有账号会保留原资料，不用试用数据覆盖。</small>':''}<p class="error" id="login-error" role="alert"></p><div class="modal-foot"><button class="btn primary" type="submit">登录并继续 ${I('arrow')}</button></div></form>`)}
function choice(name,val,label,checked,type='checkbox'){return `<label class="choice"><input type="${type}" name="${name}" value="${esc(val)}" ${checked?'checked':''}><span>${esc(label)}</span></label>`}
function startOnboard(){profileDraft=structuredClone(state().profile||{name:'',goal:'habit',motivation:'',current:'',level:'beginner',days:[0,2,5],minutes:20,equipment:['bodyweight'],place:'mixed',likes:['walking','strength'],limitations:'',adult:false,consent:false});onboardStep=0;onboard()}
function onboard(){const p=profileDraft;let body='';if(onboardStep===0)body=`<div class="form-field"><label for="intake-text">先用自己的话，讲讲现状和目标</label><textarea id="intake-text" placeholder="比如：半年没运动，想改善体力。周一周三周日晚上能练，每次20分钟，在家或散步都行。" maxlength="1500"></textarea><small>${data.capabilities.ai?'点击整理时，这段话会发给 AI 提取档案；你可以核对修改。':'当前使用基础规则整理，后面的信息仍可以逐项填写。'}</small><button class="btn ghost" type="button" data-action="intake">${I('spark')} 从这段话整理档案</button><span id="intake-info" class="small-text muted"></span></div><p class="intro">先聊聊你。比起一个漂亮的数字，我们更关心你想让生活发生什么改变。</p><div class="form-field"><label for="name">怎么称呼你</label><input id="name" name="name" value="${esc(p.name)}" maxlength="30" placeholder="你的昵称" required></div><div class="form-field"><label>现在最想实现什么</label><div class="chips">${Object.entries(goalNames).map(([id,n])=>choice('goal',id,n,p.goal===id,'radio')).join('')}</div></div><div class="form-field"><label for="motivation">用自己的话说说，为什么想运动</label><textarea id="motivation" name="motivation" maxlength="1000" placeholder="比如：下班后有精神一点，周末能陪家人走得更远。">${esc(p.motivation)}</textarea></div>`;else if(onboardStep===1)body=`<p class="intro">不需要先证明自己。告诉我真实的现状，计划会从这里开始。</p><div class="form-field"><label for="current">最近几周，你一般怎么运动</label><textarea id="current" name="current" maxlength="1000" placeholder="比如：偶尔散步，已经半年没规律运动了。">${esc(p.current)}</textarea></div><div class="form-field"><label>哪个更接近你</label><div class="chips">${[['beginner','刚开始运动'],['returning','想重新开始'],['regular','已经有些习惯']].map(([id,n])=>choice('level',id,n,p.level===id,'radio')).join('')}</div></div><div class="form-field"><label for="limitations">有需要特别留意的身体情况吗</label><textarea id="limitations" name="limitations" maxlength="1000" placeholder="近期不适、伤病或医生给出的限制；没有可以留空。">${esc(p.limitations)}</textarea><small>身体情况会作为注意事项纳入方案，请补充医生已明确的运动限制；一般风险不会阻止生成。</small></div><label class="check-row"><input type="checkbox" name="adult" ${p.adult?'checked':''} required>我已年满 18 周岁</label>`;else body=`<p class="intro">留一点真实可用的时间。安排可以修改，第一周先用来找到合适的节奏。</p><div class="form-field"><label>哪些天比较有空（最多五天）</label><div class="chips">${dayNames.map((n,i)=>choice('days',i,n,p.days.includes(i))).join('')}</div></div><div class="form-grid"><div class="form-field"><label for="minutes">单次可用时间</label><select id="minutes" name="minutes">${[10,15,20,25,30,35,40,45].map(n=>`<option value="${n}" ${p.minutes===n?'selected':''}>${n} 分钟</option>`).join('')}</select></div><div class="form-field"><label for="place">常用场地</label><select id="place" name="place">${[['mixed','室内外都可以'],['home','主要在家'],['outdoor','主要户外']].map(([id,n])=>`<option value="${id}" ${p.place===id?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="form-field"><label>喜欢的运动方式</label><div class="chips">${[['walking','步行 / 轻松活动'],['strength','基础力量']].map(([id,n])=>choice('likes',id,n,p.likes.includes(id))).join('')}</div></div><div class="form-field"><label>手边的器械</label><div class="chips">${[['bodyweight','自重即可'],['dumbbell','哑铃'],['band','弹力带']].map(([id,n])=>choice('equipment',id,n,p.equipment.includes(id))).join('')}</div><small>首版以自重动作建立基础，暂不安排额外负重。</small></div><label class="check-row"><input type="checkbox" name="consent" ${p.consent?'checked':''} required>同意保存必要运动档案和训练反馈，用于计划调整与周期跟进</label>`;showModal(['先说说，想改变什么','了解现在的你','给运动留一点空间'][onboardStep],`<div class="onboard-progress">${[0,1,2].map(i=>`<span class="${i<=onboardStep?'active':''}"></span>`).join('')}</div><form id="onboard-form">${body}<p id="onboard-error" class="error" role="alert"></p><div class="modal-foot">${onboardStep?'<button type="button" class="btn ghost" data-action="onboard-back">上一步</button>':''}<button type="submit" class="btn primary">${onboardStep===2?'生成我的试行安排':'继续'} ${I('arrow')}</button></div></form>`)}
function collectOnboard(){const f=new FormData($('#onboard-form'));if(onboardStep===0){profileDraft.name=f.get('name')?.trim()||'运动者';profileDraft.goal=f.get('goal');profileDraft.motivation=f.get('motivation')}else if(onboardStep===1){profileDraft.current=f.get('current');profileDraft.level=f.get('level');profileDraft.limitations=f.get('limitations');profileDraft.adult=f.has('adult')}else{profileDraft.days=f.getAll('days').map(Number);profileDraft.minutes=Number(f.get('minutes'));profileDraft.place=f.get('place');profileDraft.likes=f.getAll('likes');profileDraft.equipment=f.getAll('equipment');profileDraft.consent=f.has('consent')}}
function openCoach(session=null){chatSession=session||null;drawer.hidden=false;renderCoach();$('#chat-text')?.focus()}
function renderCoach(){drawer.innerHTML=`<div class="coach-head"><div class="avatar">${I('spark')}</div><div><strong>你的运动教练</strong><small>${chatSession?'正在商量这次训练':'了解你的目标，也记得你的反馈'}</small></div><button class="icon-btn" data-action="close-coach" aria-label="关闭教练">${I('close')}</button></div><div class="chat-list" id="chat-list">${state().chat.length?state().chat.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${esc(m.text)}</div>`).join(''):'<div class="message assistant">你好，我们可以聊聊现在的安排。时间、场地或感受有变化，告诉我就好。</div>'}${sending?`<div class="message user">${esc(pendingText)}</div><div class="message assistant">正在结合你的安排和反馈想一想…</div>`:''}${proposalId?`<div class="proposal-box"><strong>有一份待确认的调整</strong><p>先看看具体改变，再决定是否采用。</p><div class="actions"><button class="btn primary small" data-action="view-proposal" data-id="${proposalId}">查看调整 ${I('arrow')}</button></div></div>`:''}</div><form class="chat-compose" id="chat-form"><div class="chips"><button class="btn small ghost" type="button" data-action="quick-coach" data-text="今天只有十分钟">只有十分钟</button><button class="btn small ghost" type="button" data-action="quick-coach" data-text="这周轻一点">这周轻一点</button><button class="btn small ghost" type="button" data-action="quick-coach" data-text="今天想休息">今天想休息</button></div><div class="chat-input-row"><textarea id="chat-text" name="text" aria-label="发给教练的话" placeholder="比如：明天出差，想换成室内活动…" maxlength="1500" rows="2" required></textarea><button class="btn primary" type="submit" aria-label="发送">${I('send')}</button></div><div class="coach-mode">${data.capabilities.ai?'AI 理解你的想法，正式安排受模板和规则约束。':'基础教练模式 · 支持缩短、改期、室内替换、休息和重新开始。'}<br>重要变更会先给你预览，采用后才生效。</div></form>`;const list=$('#chat-list');list.scrollTop=list.scrollHeight}
async function sendChat(text){if(!text.trim()||sending)return;if(!state().profile){toast('先建立运动档案，教练才能了解你的安排');return}sending=true;pendingText=text;renderCoach();const form=$('#chat-form'),buttons=form?.querySelectorAll('button');buttons?.forEach(b=>b.disabled=true);const area=$('#chat-text');if(area)area.value='';try{const out=await mutate('/coach',{text,session_id:chatSession});proposalId=out.result.proposal_id;renderCoach()}catch(e){toast(e.message);if(area)area.value=text}finally{sending=false;pendingText='';if(!drawer.hidden)renderCoach();buttons?.forEach(b=>b.disabled=false)}}
async function viewProposal(id){const p=await api('/proposals/'+id),old=new Map((state().plan?.sessions||[]).map(s=>[s.id,s]));showModal('先看看，这样调整合适吗',`<p class="intro">${esc(p.summary)}</p>${p.plan.risk?.message?`<p class="privacy-note">${esc(p.plan.risk.message)}</p>`:''}<div class="privacy-note">采用后更新正式计划和后续提醒。过去的实际训练记录保留。</div>${p.plan.sessions.filter(s=>s.kind!=='rest'||(old.has(s.id)&&old.get(s.id).kind!=='rest')).map(s=>{const before=old.get(s.id),diff=before&&(before.minutes!==s.minutes||before.date!==s.date||before.kind!==s.kind);return `<div class="record-row"><div class="record-icon">${I(iconFor(s))}</div><div><p>${esc(s.title)}</p><small>${fmt(s.date,{month:'numeric',day:'numeric',weekday:'short'})} · ${s.minutes} 分钟${diff?' · 已调整':''}</small>${diff?`<small style="display:block;margin-top:4px">原安排：${fmt(before.date,{month:'numeric',day:'numeric'})} · ${before.minutes} 分钟</small>`:''}</div></div>`}).join('')}<p id="proposal-error" class="error" role="alert"></p><div class="modal-foot"><button class="btn ghost" data-action="close-modal">暂时不改</button><button class="btn primary" data-action="apply-proposal" data-id="${id}">采用这份安排 ${I('check')}</button></div>`)}
function feedback(id=null){const s=id?sessionBy(id):null,r=s?recordFor(s):null,measured=!!(s&&timerSession===s.id&&timerStart),elapsed=measured?Date.now()-timerStart:0,suggestedStatus=measured&&elapsed<s.minutes*60000*.8?'partial':'completed';showModal(s?'记录这次运动的感受':'记录一次自主活动',`<p class="intro">${s?esc(s.title)+' · '+fmt(s.date):'散步、打球、游泳，计划之外的活动也值得留下。'}<br>真实反馈比一张全绿的课表更有用。</p><form id="feedback-form" data-id="${s?.id||''}">${!s?`<div class="form-field"><label for="activity">活动名称</label><input id="activity" name="activity" placeholder="比如：和朋友打羽毛球" maxlength="80" required></div><div class="form-field"><label for="record-date">活动日期</label><input id="record-date" type="date" name="date" value="${data.today}" max="${data.today}" required></div>`:`<input type="hidden" name="date" value="${s.date}">`}<div class="form-field"><label>这次完成了多少</label><div class="chips">${[['completed','完整完成'],['partial','完成一部分'],['skipped','没能完成'],['rest','主动休息']].map(([v,n])=>choice('status',v,n,(r?.status||suggestedStatus)===v,'radio')).join('')}</div></div><div class="form-field"><label for="actual-minutes">实际活动时长（分钟）</label><input id="actual-minutes" type="number" name="minutes" value="${r?.minutes??(measured?Math.max(0,Math.round(elapsed/60000)):s?.minutes||20)}" min="0" max="300" required><small>按实际时长记录；不足 1 分钟的尝试可记 0 并选「完成一部分」。</small></div><div class="form-field"><label>整体感觉怎么样</label><div class="chips">${[['easy','轻松，还有余力'],['okay','刚刚好'],['hard','有点吃力']].map(([v,n])=>choice('effort',v,n,(r?.effort||'okay')===v,'radio')).join('')}</div></div><label class="check-row"><input type="checkbox" name="pain" ${r?.pain?'checked':''}>出现了疼痛或异常不适</label><div class="form-field"><label for="record-note">想留给自己或教练的话</label><textarea id="record-note" name="note" placeholder="比如：今天状态不错；或加班后有点累。" maxlength="1000">${esc(r?.note||'')}</textarea></div><p id="feedback-error" class="error" role="alert"></p><div class="modal-foot"><button class="btn ghost" type="button" data-action="close-modal">再想想</button><button class="btn primary" type="submit">保存这次记录 ${I('check')}</button></div></form>`)}
function training(id){const s=sessionBy(id);if(!s||s.kind==='rest')return;if(state().blocked){toast('请先确认年龄适用范围');return}if(s.date!==data.today){toast('只能开始今天的训练；想提前练可以先调整日期');return}if(timerSession!==id){timerStart=0;timerSession=id}showModal(s.title,`${state().risk?.message?`<p class="privacy-note">${esc(state().risk.message)}</p>`:''}<div class="train-timer"><div class="eyebrow" style="justify-content:center">A LITTLE TIME FOR YOURSELF</div><div class="timer-value" id="timer-value">00:00</div><div class="timer-label">预计 ${s.minutes} 分钟 · 轻松强度 · 随时可以停下</div><div class="actions" style="justify-content:center"><button class="btn primary" data-action="timer-start" data-id="${id}">${I('play')} 开始计时</button><button class="btn ghost" data-action="feedback" data-id="${id}">结束并记录</button></div></div><div id="current-step" class="privacy-note">先看看下面的安排，准备好再开始。计时只是辅助，不要求赶进度。</div>${s.steps.map((x,i)=>`<div class="step"><div class="step-index">${i+1}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div><span class="step-time">${x.minutes} 分钟</span></div>`).join('')}<p class="small-text muted">如有疼痛、头晕等异常不适，先停止并记录，不要为了完成计时继续。</p>`);if(timerStart)startTimer(id)}
function startTimer(id){if(!timerStart)timerStart=Date.now();if(timerInterval)clearInterval(timerInterval);const update=()=>{const s=sessionBy(id),seconds=Math.floor((Date.now()-timerStart)/1000),el=$('#timer-value');if(!el)return;el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;let accumulated=0,active=s.steps.at(-1);for(const step of s.steps){accumulated+=step.minutes*60;if(seconds<accumulated){active=step;break}}$('#current-step').textContent=seconds>=s.minutes*60?'预计时间到了。可以按感受结束并记录，不会自动标记完成。':'现在可以：'+active.title+'。'+active.detail};update();timerInterval=setInterval(update,1000);const b=modal.querySelector('[data-action="timer-start"]');if(b){b.disabled=true;b.innerHTML=I('clock')+' 正在计时'}}
function adjust(id){chatSession=id;showModal('这次安排，想怎么调整？',`<p class="intro">${esc(sessionBy(id)?.title||'这次训练')}<br>快捷选择也会先生成预览，由你决定是否采用。</p><div class="stack"><button class="btn ghost" data-action="adjust-short" data-id="${id}">${I('clock')} 今天只有 10 分钟</button><button class="btn ghost" data-action="adjust-indoor" data-id="${id}">${I('home')} 换成室内轻松活动</button><form id="move-form" data-id="${id}"><div class="form-field"><label for="move-date">改到另一天</label><div class="flex"><input id="move-date" name="date" type="date" min="${data.today}" required><button class="btn ghost" style="flex-shrink:0">预览改期</button></div></div></form><button class="btn ghost" data-action="adjust-rest" data-id="${id}">${I('leaf')} 这次改为休息</button></div><p class="error" id="adjust-error" role="alert"></p>`)}
async function quickAdjust(text,id){closeModal();openCoach(id);await sendChat(text);if(proposalId)await viewProposal(proposalId)}
async function nextWeek(){if(data.direction[0]==='consider'){showModal('下一步，可以小一点',`<p class="intro">${esc(data.direction[1])}</p><label class="check-row"><input id="recovered" type="checkbox">近期训练后恢复良好，没有异常不适</label><p class="small-text muted">可以先保持；如果选择进阶，单次最多增加 5 分钟，仍由你预览确认。</p><div class="modal-foot"><button class="btn ghost" data-action="next-draft">保持当前节奏</button><button class="btn primary" data-action="next-progress">确认恢复，预览进阶</button></div><p id="next-error" class="error" role="alert"></p>`)}else await nextDraft(false,false)}
async function nextDraft(progress,recovered){const out=await mutate('/plan/next',{progress,recovered});proposalId=out.result.proposal_id;await viewProposal(proposalId)}
function showNotices(){showModal('给你的提醒',`${data.notices.length?data.notices.map(n=>`<div class="version-list"><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small class="muted">${esc(n.created_at)} UTC</small></div>`).join(''):'<div class="empty"><div class="empty-icon">'+I('bell')+'</div><p>暂时没有新提醒。<br>到你设置的时间，站内提醒会出现在这里。</p></div>'}<p class="small-text muted">站内提醒会保存；离线时只有已配置且开启的邮件可送达。<br>邮件状态：${data.deliveries.map(x=>({sent:'已发送',pending:'待发送',sending:'发送中',uncertain:'结果未确认',cancelled:'已取消'}[x.status]||x.status)+' '+x.count).join(' · ')||'暂无发送记录'}</p><div class="modal-foot"><button class="btn ghost" data-action="reminder-settings">调整提醒偏好 ${I('arrow')}</button></div>`);api('/notices/read','POST').then(()=>{data.notices.forEach(n=>n.read=1);render()}).catch(()=>{})}
async function action(name,el){switch(name){case 'demo':el.disabled=true;data=await api('/demo','POST');page='today';render();break;case 'new-demo':el.disabled=true;data=await api('/demo','POST',{mode:'empty'});proposalId=null;drawer.hidden=true;closeModal();page='today';render();if(!state().profile)startOnboard();else toast('你已登录正式账号，可以在「我的」修改计划');break;case 'privacy':showModal('数据与隐私',`<p class="intro">你的运动计划和身体反馈默认私密，只用于向你提供计划、调整与复盘。</p><div class="review-body"><strong>保存哪些内容</strong>登录邮箱、运动档案、计划与修改历史、训练反馈、对话、提醒偏好保存在服务器。你可以在「我的」导出或删除账号数据。<strong>什么时候发送给 AI</strong>点击「整理档案」或向教练发送消息时，必要自述、近期计划与反馈会交给 DeepSeek 处理；不会为了发送普通提醒调用 AI。供应商的数据处理遵循其服务政策。<strong>提醒和邮件</strong>邮件默认只提醒你查看安排，不附身体情况；可以随时关闭或暂停。演示空间不发送邮件。<strong>删除和备份</strong>账号删除会清除在线账号及关联训练数据。服务器每日备份最多保留约 30 天，备份中的数据随保留周期到期清除。模型供应商的留存不由本站直接控制。</div><div class="modal-foot"><button class="btn primary" data-action="close-modal">知道了</button></div>`);break;case 'login':login();break;case 'close-modal':closeModal();break;case 'send-code':{const f=new FormData($('#login-form'));if(!$('#email').reportValidity())return;el.disabled=true;try{const out=await api('/auth/code','POST',{email:f.get('email'),invite:f.get('invite')});$('#login-info').textContent=out.dev_code?'本机开发验证码：'+out.dev_code+'（仅本机显示）':'验证码已发出，请查收邮箱';if(out.dev_code)$('#login-form [name="code"]').value=out.dev_code;el.textContent='60 秒后可重发';setTimeout(()=>{el.disabled=false;el.textContent='重新获取'},60000)}catch(e){el.disabled=false;$('#login-error').textContent=e.message}break}case 'onboard':startOnboard();break;case 'intake':{const text=$('#intake-text').value;if(text.trim().length<3){$('#intake-info').textContent='先写几句你的现状和想法。';break}el.disabled=true;el.textContent='正在整理…';try{collectOnboard();const out=await api('/intake','POST',{text});Object.assign(profileDraft,out.patch);onboard();$('#intake-text').value=text;$('#intake-info').textContent=out.reply;toast(out.mode==='ai'?'AI 已整理，请逐项核对':'已整理明确的信息，请继续核对')}finally{el.disabled=false}break;}case 'onboard-back':collectOnboard();onboardStep--;onboard();break;case 'select-day':selected=el.dataset.id;page='plan';render();break;case 'coach':openCoach();break;case 'close-coach':drawer.hidden=true;break;case 'quick-coach':if(drawer.hidden)openCoach();await sendChat(el.dataset.text);break;case 'view-proposal':await viewProposal(el.dataset.id);break;case 'apply-proposal':{el.disabled=true;try{const out=await mutate('/proposals/'+el.dataset.id+'/apply');proposalId=null;closeModal();if(state().upcoming){page='plan';selected=state().upcoming.sessions.find(s=>s.kind!=='rest')?.id||null}render();toast(out.result)}catch(e){$('#proposal-error').textContent=e.message;el.disabled=false}break}case 'training':training(el.dataset.id);break;case 'timer-start':startTimer(el.dataset.id);break;case 'feedback':feedback(el.dataset.id);break;case 'free-record':feedback();break;case 'adjust':adjust(el.dataset.id);break;case 'adjust-short':await quickAdjust('今天只有 10 分钟',el.dataset.id);break;case 'adjust-indoor':await quickAdjust('今天换成室内活动',el.dataset.id);break;case 'adjust-rest':await quickAdjust('今天想休息',el.dataset.id);break;case 'undo':{const out=await mutate('/plan/undo');toast(out.result);break}case 'review':{el.disabled=true;const out=await mutate('/reviews',{cadence:el.dataset.cadence});toast('已根据实际记录生成回顾');break}case 'next-week':await nextWeek();break;case 'next-draft':await nextDraft(false,false);break;case 'next-progress':if(!$('#recovered').checked){$('#next-error').textContent='请先确认近期恢复情况，或选择保持当前节奏。';return}await nextDraft(true,true);break;case 'notices':showNotices();break;case 'reminder-settings':closeModal();page='me';render();break;case 'learn':showModal('为什么不需要补欠课',`<p class="intro">计划服务于身体和生活。把漏掉的训练集中到后面，可能使活动突然增加，也会挤掉恢复时间。</p><p class="small-text muted">更好的下一步是记录没能完成的原因，保留适当恢复，重新安排后面的训练。暂时中断时，先从可接受的起点回来。</p><div class="privacy-note">本周完成情况会区分原始计划、调整后的安排和真实活动；不会通过删除训练把结果变成“全部完成”。</div><p class="sources">参考：<a href="https://www.niddk.nih.gov/health-information/weight-management/tips-get-active/tips-starting-physical-activity" target="_blank" rel="noopener">NIDDK · 从少量活动开始，逐步增加</a></p>`);break;case 'logout':await api('/auth/logout','POST');drawer.hidden=true;closeModal();proposalId=null;landing();break;case 'delete':showModal('删除这个空间里的数据',`<p class="intro">将删除账号、会话、个人档案、计划、训练记录和提醒。删除后无法恢复。可以先导出一份备份。</p><div class="actions"><a class="btn ghost" href="/api/export">先导出数据</a><button class="btn danger" data-action="delete-confirm">确认删除</button></div>`);break;case 'delete-confirm':await api('/account','DELETE');closeModal();drawer.hidden=true;landing();toast('账号与训练数据已删除');break}}
document.addEventListener('click',async e=>{const p=e.target.closest('[data-page]');if(p){page=p.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});return}const el=e.target.closest('[data-action]');if(el){try{await action(el.dataset.action,el)}catch(err){toast(err.message);el.disabled=false}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type="submit"]'),fd=new FormData(form);if(submit)submit.disabled=true;try{if(form.id==='login-form'){data=await api('/auth/verify','POST',{...Object.fromEntries(fd),import_trial:fd.has('import_trial')});proposalId=null;drawer.hidden=true;closeModal();page='today';render();if(!state().profile)startOnboard()}else if(form.id==='onboard-form'){collectOnboard();if(onboardStep<2){onboardStep++;onboard()}else{if(!profileDraft.days.length||profileDraft.days.length>5)throw new Error('请选择 1–5 个可用训练日');if(!profileDraft.likes.length)throw new Error('至少选择一种喜欢的运动方式');const out=await mutate('/profile',{profile:profileDraft},'PUT');closeModal();page=state().blocked?'me':'plan';render();toast(out.result)}}else if(form.id==='feedback-form'){const status=fd.get('status');const out=await mutate('/records',{session_id:form.dataset.id||null,date:fd.get('date'),status,minutes:['rest','skipped'].includes(status)?0:Number(fd.get('minutes')),effort:fd.get('effort'),pain:fd.has('pain'),note:fd.get('note'),activity:fd.get('activity')||sessionBy(form.dataset.id)?.title||'自主活动'});closeModal();timerStart=0;timerSession=null;toast(out.result)}else if(form.id==='chat-form'){await sendChat(fd.get('text'))}else if(form.id==='move-form'){await quickAdjust('改到 '+fd.get('date'),form.dataset.id)}else if(form.id==='settings-form'){const obj=Object.fromEntries(fd);for(const n of ['daily','weekly','monthly','followup','email'])obj[n]=fd.has(n);const out=await mutate('/settings',obj,'PUT');toast(out.result)}}catch(err){const id={ 'login-form':'login-error','onboard-form':'onboard-error','feedback-form':'feedback-error','settings-form':'settings-error','move-form':'adjust-error'}[form.id],el=id?$('#'+id):null;if(el)el.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('change',e=>{if(e.target.name==='status'&&$('#actual-minutes')&&['skipped','rest'].includes(e.target.value))$('#actual-minutes').value=0});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden)drawer.hidden=true;if(e.target.id==='chat-text'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('online',()=>toast('已重新连接，可以继续记录。'));
window.addEventListener('offline',()=>toast('当前离线，暂时无法同步。恢复连接后再保存记录。'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
load();
